#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_CAVES 50001

bool is_prime[MAX_CAVES];
int adj[MAX_CAVES][MAX_CAVES];
int deg[MAX_CAVES];
int best_count = -1;
int best_last_prime = -1;

void sieve(int n) {
    memset(is_prime, true, sizeof(is_prime));
    is_prime[0] = is_prime[1] = false;
    for (int i = 2; i * i <= n; i++) {
        if (is_prime[i]) {
            for (int j = i * i; j <= n; j += i)
                is_prime[j] = false;
        }
    }
}

void dfs(int u, int count, int last_prime) {
    if (is_prime[u]) {
        count++;
        last_prime = u;
    }

    if (deg[u] == 0) {
        if (count > best_count || (count == best_count && last_prime > best_last_prime)) {
            best_count = count;
            best_last_prime = last_prime;
        }
        return;
    }

    for (int i = 0; i < deg[u]; i++) {
        int v = adj[u][i];
        dfs(v, count, last_prime);
    }
}

int main() {
    int n, start;
    scanf("%d %d", &n, &start);
    sieve(n);

    for (int i = 1; i <= n; i++) {
