int main() {
    int N, start;
    cin >> N >> start;

    // Find number of rows
    int R = (int)((-1 + sqrt(1 + 8.0*N)) / 2);

    // dp[c] = {max primes from c to leaf, last prime cave on that path}
    vector<pair<int,int>> dp(N + 1, {0, -1});

    // Process from bottom row up
    for (int c = N; c >= start; c--) {
        // Find row of c
        int r = (int)((-1 + sqrt(1 + 8.0*(c-1))) / 2) + 1;
        // row r starts at r*(r-1)/2 + 1
        int rowStart = r * (r - 1) / 2 + 1;
        int p = c - rowStart; // 0-indexed position

        int leftChild = r * (r + 1) / 2 + 1 + p;
        int rightChild = r * (r + 1) / 2 + 1 + p + 1;

        int primeVal = isPrime(c) ? 1 : 0;
        int lastPrime = isPrime(c) ? c : -1;

        if (leftChild > N) {
            // leaf node
            dp[c] = {primeVal, lastPrime};
        } else {
            // choose better child
            auto left = dp[leftChild];
            auto right = dp[rightChild <= N ? rightChild : leftChild];

            pair<int,int> best;
            if (left.first >= right.first) best = left;
            else best = right;

            int total = primeVal + best.first;
            int lp = (best.second != -1) ? best.second : lastPrime;
            if (isPrime(c)) lp = (best.second != -1) ? best.second : c;
            else lp = best.second;
            if (isPrime(c) && best.second == -1) lp = c;

            dp[c] = {total, lp};
        }
    }

    cout << dp[start].first << " " << dp[start].second << endl;
    return 0;
}

