            if (isPrime[i]) {
                for (int j = i * i; j <= N; j += i) {
                    isPrime[j] = false;
                }
            }
        }

        List<Integer> path = new ArrayList<>();
        boolean[] visited = new boolean[N + 1];
        int current = start;

        while (current != 0 && current <= N && !visited[current]) {
            visited[current] = true;
            path.add(current);
            int next = 0;
            int temp = current;
            while (temp > 0) {
                int digit = temp % 10;
                next += digit * digit;
                temp /= 10;
            }
            current = next;
        }

        int primeCount = 0;
        int lastPrime = -1;
        for (int cave : path) {
            if (isPrime[cave]) {
                primeCount++;
                lastPrime = cave;
            }
        }

        if (lastPrime == -1) {
            System.out.println(primeCount);
        } else {
            System.out.println(primeCount + " " + lastPrime);
        }
    }
