public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static boolean isPrime(long x) {
        if (x < 2) return false;
        if (x % 2 == 0) return x == 2;
        for (long d = 3; d * d <= x; d += 2) {
            if (x % d == 0) return false;
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        long n, start;
        try {
            n = fs.nextLong();
            start = fs.nextLong();
        } catch (Exception e) {
            return;
        }

        long primeCount = 0;
        long lastPrime = -1;

        for (long x = start; x >= 1; x /= 2) {
            if (isPrime(x)) {
                primeCount++;
                lastPrime = x;
            }
            if (x == 1) break;
        }

        if (primeCount == 0) {
            System.out.println("0 -1");
        } else {
            System.out.println(primeCount + " " + lastPrime);
        }
    }
}

import sys
import math

def sieve(n):
    """Return a boolean list is_prime where is_prime[i] is True if i is prime."""
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(math.isqrt(n)) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    return is_prime

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])
    start = int(data[1])

    is_prime = sieve(N)

    # dp[i] = (max_primes_count, last_prime_cave) for path ending at i
    # last_prime_cave is the smallest prime cave number on the best path ending at i
    dp = [(0, 0)] * (N + 1)

    for cave in range(1, N + 1):
        best_count = 0
        best_last = 0

        # Option 1: coming from cave-1 if it exists
        if cave > 1:
            cnt, last = dp[cave - 1]
            if cnt > best_count or (cnt == best_count and last > best_last):
                best_count = cnt
                best_last = last

        # Option 2: coming from any divisor
        for d in range(1, int(math.isqrt(cave)) + 1):
            if cave % d == 0:
                d1 = d
                d2 = cave // d
                for divisor in (d1, d2):
                    if divisor < cave:
                        cnt, last = dp[divisor]
                        if cnt > best_count or (cnt == best_count and last > best_last):
                            best_count = cnt
                            best_last = last

        # Add current cave if it is prime
        if is_prime[cave]:
            best_count += 1
            best_last = cave

        dp[cave] = (best_count, best_last)

    # We want the path starting from 'start' descending, so result is dp[start]
    count, last_prime = dp[start]
    print(count, last_prime)

if __name__ == "__main__":
    solve()

