    prime_count = 0
    last_prime = -1

    # Descending route: repeatedly go to floor(current / 2) until reaching 1
    cur = start
    while cur >= 1:
        if is_prime(cur):
            prime_count += 1
            last_prime = cur
        if cur == 1:
            break
        cur //= 2

    print(prime_count, last_prime)

